CREATE OR REPLACE FUNCTION private.account_id_for_booking(p_bookingid bigint, p_khachhangid bigint)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT COALESCE(
    (
      SELECT notification."TaiKhoanID"::bigint
      FROM public."ThongBao" AS notification
      JOIN public."TaiKhoan" AS account
        ON account."TaiKhoanID" = notification."TaiKhoanID"
      WHERE notification."BookingID" = p_bookingid
        AND notification."DonHangID" IS NULL
        AND notification."LoaiThongBao" = 'order_created'
        AND account."KhachHangID" = p_khachhangid
        AND account."TrangThai" = 'Hoạt động'
      ORDER BY notification."ThoiGianGui", notification."ThongBaoID"
      LIMIT 1
    ),
    private.account_id_for_customer(p_khachhangid)
  );
$function$
;

COMMENT ON FUNCTION "private"."account_id_for_booking"(p_bookingid bigint, p_khachhangid bigint) IS 'Resolves the active account that submitted a booking, using its original booking notification.';

CREATE OR REPLACE FUNCTION private.account_id_for_customer(p_khachhangid bigint)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT account."TaiKhoanID"
  FROM public."TaiKhoan" AS account
  WHERE account."KhachHangID" = p_khachhangid
    AND account."TrangThai" = 'Hoạt động'
  ORDER BY account."TaiKhoanID"
  LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION private.apply_booking_promotion_to_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  booking_row public."Booking"%ROWTYPE;
  promotion public."KhuyenMai"%ROWTYPE;
  discount_amount numeric(18,2);
BEGIN
  IF TG_OP='UPDATE' AND OLD."TongTien" IS NOT DISTINCT FROM NEW."TongTien" AND OLD."TienGiamDoDiem" IS NOT DISTINCT FROM NEW."TienGiamDoDiem" AND OLD."PhiGiaoHang" IS NOT DISTINCT FROM NEW."PhiGiaoHang" AND OLD."KhuyenMaiID" IS NOT DISTINCT FROM NEW."KhuyenMaiID" THEN RETURN NEW; END IF;
  IF NEW."BookingID" IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT *
  INTO booking_row
  FROM public."Booking"
  WHERE "BookingID" = NEW."BookingID";
  IF NOT FOUND OR booking_row."KhuyenMaiID" IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT *
  INTO promotion
  FROM public."KhuyenMai"
  WHERE "KhuyenMaiID" = booking_row."KhuyenMaiID";
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;
  IF promotion."TrangThai"<>'Hoạt động' OR promotion."NgayBatDau">current_date OR promotion."NgayKetThuc"<current_date
     OR (promotion."GiaTriDonToiThieu" IS NOT NULL AND NEW."TongTien"<promotion."GiaTriDonToiThieu")
     OR ((lower(coalesce(promotion."DieuKienApDung",'')) LIKE '%first_order_only%' OR lower(coalesce(promotion."DieuKienApDung",'')) LIKE '%don hang dau tien%' OR lower(coalesce(promotion."DieuKienApDung",'')) LIKE '%đơn hàng đầu tiên%') AND EXISTS(SELECT 1 FROM public."DonHang" WHERE "KhachHangID"=NEW."KhachHangID" AND "DonHangID"<>NEW."DonHangID")) THEN
    IF booking_row."KhuyenMaiDaTru" THEN
      UPDATE public."KhuyenMai"
      SET "SoLuongSuDung" = "SoLuongSuDung" + 1
      WHERE "KhuyenMaiID" = booking_row."KhuyenMaiID"
        AND "SoLuongSuDung" IS NOT NULL;
    END IF;
    UPDATE public."Booking"
    SET "KhuyenMaiID" = NULL,
        "KhuyenMaiDaTru" = false
    WHERE "BookingID" = NEW."BookingID";
    NEW."KhuyenMaiID" := NULL;
    NEW."TienGiamKhuyenMai" := 0;
    NEW."ThanhTien" := greatest(
      NEW."TongTien" + NEW."PhiGiaoHang" - NEW."TienGiamDoDiem",
      0
    );
    RETURN NEW;
  END IF;
  discount_amount := CASE
    WHEN promotion."LoaiKhuyenMai" = 'Phần trăm'
      THEN NEW."TongTien" * promotion."GiaTriGiam" / 100
    ELSE promotion."GiaTriGiam"
  END;
  IF promotion."MucGiamToiDa" IS NOT NULL THEN
    discount_amount := least(discount_amount, promotion."MucGiamToiDa");
  END IF;
  NEW."KhuyenMaiID" := booking_row."KhuyenMaiID";
  NEW."TienGiamKhuyenMai" := greatest(least(discount_amount, NEW."TongTien"), 0);
  NEW."ThanhTien" := greatest(
    NEW."TongTien" + NEW."PhiGiaoHang" - NEW."TienGiamDoDiem" - NEW."TienGiamKhuyenMai",
    0
  );
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.broadcast_web_message_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    item jsonb;
    scopes text[] := ARRAY[]::text[];
    channel record;
BEGIN
    -- Include both sides of UPDATE/move and DELETE; never disclose row data.
    FOREACH item IN ARRAY ARRAY[CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END,
                                CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END] LOOP
        IF item IS NULL THEN CONTINUE; END IF;
        IF item->>'DonHangID' IS NOT NULL THEN
            scopes := array_append(scopes, 'order:' || (item->>'DonHangID'));
        ELSE
            scopes := scopes || ARRAY(
                SELECT 'support:' || customer."TaiKhoanID"::text
                FROM public."TaiKhoan" customer
                JOIN public."TaiKhoan" staff ON staff."TaiKhoanID" = CASE
                    WHEN customer."TaiKhoanID" = (item->>'NguoiGuiID')::bigint
                    THEN (item->>'NguoiNhanID')::bigint ELSE (item->>'NguoiGuiID')::bigint END
                WHERE customer."TaiKhoanID" IN ((item->>'NguoiGuiID')::bigint, (item->>'NguoiNhanID')::bigint)
                  AND customer."KhachHangID" IS NOT NULL AND customer."NhanVienID" IS NULL
                  AND staff."NhanVienID" IS NOT NULL
            );
        END IF;
    END LOOP;
    FOR channel IN SELECT topic FROM private.web_message_channels
        WHERE scope = ANY(scopes) AND expires_at > clock_timestamp()
        ORDER BY expires_at DESC LIMIT 8 LOOP
        BEGIN
            PERFORM realtime.send('{}'::jsonb, 'changed', channel.topic, false);
        EXCEPTION WHEN query_canceled OR OTHERS THEN
            -- Delivery is best effort: a Realtime outage must not break message writes.
            RAISE WARNING 'Web message signal delivery failed';
        END;
    END LOOP;
    RETURN NULL;
EXCEPTION WHEN query_canceled OR OTHERS THEN
    RAISE WARNING 'Web message signal unavailable';
    RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.can_access_order(order_id bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT (SELECT auth.uid()) IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public."DonHang" AS order_record
      WHERE order_record."DonHangID" = order_id
        AND (
          order_record."KhachHangID" = (SELECT private.current_customer_id())
          OR (SELECT private.is_staff())
        )
    );
$function$
;

CREATE OR REPLACE FUNCTION private.copy_booking_delivery_fee_to_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  pickup_fee numeric(12, 2);
  delivery_fee numeric(12, 2);
BEGIN
  IF NEW."BookingID" IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT "PickupDeliveryFee", "DeliveryFee"
  INTO pickup_fee, delivery_fee
  FROM public."Booking"
  WHERE "BookingID" = NEW."BookingID";

  IF FOUND THEN
    NEW."PhiGiaoHang" := coalesce(pickup_fee, 0) + coalesce(delivery_fee, 0);
    NEW."ThanhTien" := greatest(
      NEW."TongTien" + NEW."PhiGiaoHang"
        - NEW."TienGiamDoDiem" - NEW."TienGiamKhuyenMai",
      0
    );
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.create_legacy_order_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
	INSERT INTO public."HoaDon" (
		"MaHoaDon",
		"DonHangID",
		"TongTien",
		"GiamGia",
		"PhiGiaoHang",
		"ThanhTien",
		"TrangThai"
	) VALUES (
		'HD-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISS') || '-' ||
			substr(replace(gen_random_uuid()::text, '-', ''), 1, 8),
		NEW."DonHangID",
		NEW."TongTien",
		NEW."TienGiamDoDiem" + NEW."TienGiamKhuyenMai",
		NEW."PhiGiaoHang",
		NEW."ThanhTien",
		'Chưa thanh toán'
	);
	RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.create_order_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
	INSERT INTO public.hoadon (
		mahoadon,
		donhangid,
		tongtien,
		giamgia,
		phigiaohang,
		thanhtien,
		trangthai
	) VALUES (
		'HD-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISS') || '-' ||
			substr(replace(gen_random_uuid()::text, '-', ''), 1, 8),
		NEW.donhangid,
		NEW.tongtien,
		NEW.tiengiamdodiem + NEW.tiengiamkhuyenmai,
		NEW.phigiaohang,
		NEW.thanhtien,
		'Chưa thanh toán'
	);
	RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.current_account_id()
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT account."TaiKhoanID"
  FROM public."TaiKhoan" AS account
  WHERE account."UserAuthId" = (SELECT auth.uid())
    AND account."TrangThai" = 'Hoạt động';
$function$
;

CREATE OR REPLACE FUNCTION private.current_customer_id()
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT account."KhachHangID"
  FROM public."TaiKhoan" AS account
  JOIN public."KhachHang" AS customer
    ON customer."KhachHangID" = account."KhachHangID"
  WHERE account."UserAuthId" = (SELECT auth.uid())
    AND account."TrangThai" = 'Hoạt động'
    AND customer."TrangThai" = 'Hoạt động';
$function$
;

CREATE OR REPLACE FUNCTION private.current_employee_id()
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT account."NhanVienID"
  FROM public."TaiKhoan" AS account
  JOIN public."NhanVien" AS employee
    ON employee."NhanVienID" = account."NhanVienID"
  WHERE account."UserAuthId" = (SELECT auth.uid())
    AND account."TrangThai" = 'Hoạt động'
    AND employee."TrangThai" = 'Hoạt động';
$function$
;

CREATE OR REPLACE FUNCTION private.default_support_account_id()
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT a."TaiKhoanID"
  FROM public."TaiKhoan" AS a
  WHERE a."NhanVienID" IS NOT NULL
    AND a."TrangThai" = 'Hoạt động'
    AND EXISTS (
      SELECT 1
      FROM public."TaiKhoan_VaiTro" AS av
      JOIN public."VaiTro" AS r ON r."VaiTroID" = av."VaiTroID"
      WHERE av."TaiKhoanID" = a."TaiKhoanID"
        AND r."TrangThai" = 'Hoạt động'
        AND (
          r."TenVaiTro" IN ('Nhân viên', 'Chủ cửa hàng')
          OR r."TenVaiTro" LIKE 'Quản lý%'
        )
    )
  ORDER BY
    CASE
      WHEN EXISTS (
        SELECT 1 FROM public."TaiKhoan_VaiTro" av
        JOIN public."VaiTro" r ON r."VaiTroID" = av."VaiTroID"
        WHERE av."TaiKhoanID" = a."TaiKhoanID"
          AND r."TenVaiTro" = 'Chủ cửa hàng'
      ) THEN 0
      WHEN EXISTS (
        SELECT 1 FROM public."TaiKhoan_VaiTro" av
        JOIN public."VaiTro" r ON r."VaiTroID" = av."VaiTroID"
        WHERE av."TaiKhoanID" = a."TaiKhoanID"
          AND r."TenVaiTro" LIKE 'Quản lý%'
      ) THEN 1
      ELSE 2
    END,
    a."TaiKhoanID"
  LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION private.has_role(role_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public."TaiKhoan" AS account
    JOIN public."TaiKhoan_VaiTro" AS account_role
      ON account_role."TaiKhoanID" = account."TaiKhoanID"
    JOIN public."VaiTro" AS app_role
      ON app_role."VaiTroID" = account_role."VaiTroID"
    WHERE account."UserAuthId" = (SELECT auth.uid())
      AND account."TrangThai" = 'Hoạt động'
      AND app_role."TenVaiTro" = role_name
      AND app_role."TrangThai" = 'Hoạt động'
  );
$function$
;

CREATE OR REPLACE FUNCTION private.is_messaging_staff()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public."TaiKhoan_VaiTro" AS av
    JOIN public."VaiTro" AS r ON r."VaiTroID" = av."VaiTroID"
    WHERE av."TaiKhoanID" = (SELECT private.current_account_id())
      AND r."TrangThai" = 'Hoạt động'
      AND (
        r."TenVaiTro" IN ('Nhân viên', 'Chủ cửa hàng')
        OR r."TenVaiTro" LIKE 'Quản lý%'
      )
  );
$function$
;

CREATE OR REPLACE FUNCTION private.is_staff()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
			SELECT (SELECT private.has_role('Nhân viên'))
				OR (SELECT private.has_role('Quản lý'))
				OR (SELECT private.has_role('Chủ cửa hàng'));
		$function$
;

CREATE OR REPLACE FUNCTION private.normalize_phone(phone_number text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
			WITH digits AS (
				SELECT regexp_replace(coalesce(phone_number, ''), '[^0-9]', '', 'g') AS value
			)
			SELECT CASE
				WHEN value = '' THEN NULL
				WHEN value LIKE '84%' THEN '+' || value
				WHEN value LIKE '0%' THEN '+84' || substr(value, 2)
				ELSE '+' || value
			END
			FROM digits;
		$function$
;

CREATE OR REPLACE FUNCTION private.notify_booking_created()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE customer_account_id bigint; customer_name text; BEGIN customer_account_id := COALESCE(private.current_account_id(), private.account_id_for_customer(NEW."KhachHangID")); SELECT "HoTen" INTO customer_name FROM public."KhachHang" WHERE "KhachHangID"=NEW."KhachHangID"; IF customer_account_id IS NOT NULL THEN INSERT INTO public."ThongBao" ("TaiKhoanID","TieuDe","NoiDung","ThoiGianGui","DaDoc","DonHangID","BookingID","LoaiThongBao") SELECT customer_account_id::integer,'Yêu cầu đặt giặt đã gửi'::varchar,('Yêu cầu '||NEW."MaBooking"||' đã được gửi. Cửa hàng sẽ tiếp nhận trong thời gian sớm nhất.')::varchar,now()::timestamp,false,NULL::integer,NEW."BookingID",'order_created'::varchar WHERE NOT EXISTS (SELECT 1 FROM public."ThongBao" notification WHERE notification."TaiKhoanID"=customer_account_id AND notification."LoaiThongBao"='order_created' AND notification."DonHangID" IS NULL AND notification."NoiDung" LIKE '%'||NEW."MaBooking"||'%'); END IF; PERFORM public.notify_staff_new_booking(NEW."BookingID",NEW."MaBooking",customer_name); RETURN NEW; END; $function$
;

CREATE OR REPLACE FUNCTION private.notify_customer_booking_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_account_id bigint;
  notification_title varchar(200);
  notification_body varchar(1000);
  notification_type varchar(50);
BEGIN
  customer_account_id := private.account_id_for_booking(NEW."BookingID", NEW."KhachHangID");

  IF customer_account_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW."TrangThai" = 'DaHuy' THEN
    notification_title := 'Đặt lịch đã được hủy';
    notification_body := ('Đặt lịch ' || NEW."MaBooking" || ' đã được hủy.');
    notification_type := 'booking_cancelled';
  ELSIF NEW."TrangThai" IS DISTINCT FROM OLD."TrangThai" THEN
    notification_title := 'Đặt lịch đã được cập nhật';
    notification_body := ('Đặt lịch ' || NEW."MaBooking" || ' đã chuyển sang trạng thái ' || NEW."TrangThai" || '.');
    notification_type := 'booking_status_updated';
  ELSE
    notification_title := 'Cửa hàng đã kiểm tra đặt lịch';
    notification_body := ('Thông tin và số lượng thực tế của đặt lịch ' || NEW."MaBooking" || ' đã được cập nhật.');
    notification_type := 'booking_updated';
  END IF;

  INSERT INTO public."ThongBao" (
    "TaiKhoanID", "DonHangID", "BookingID", "LoaiThongBao", "TieuDe", "NoiDung", "ThoiGianGui", "DaDoc"
  ) VALUES (
    customer_account_id::integer, NULL, NEW."BookingID", notification_type, notification_title,
    notification_body, now()::timestamp, false
  );

  RETURN NEW;
END;
$function$
;

COMMENT ON FUNCTION "private"."notify_customer_booking_changed"() IS 'Notifies the account that submitted the booking when staff updates it.';

CREATE OR REPLACE FUNCTION private.notify_customer_booking_deleted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_account_id bigint;
BEGIN
  customer_account_id := private.account_id_for_booking(OLD."BookingID", OLD."KhachHangID");

  IF customer_account_id IS NOT NULL THEN
    INSERT INTO public."ThongBao" (
      "TaiKhoanID", "DonHangID", "BookingID", "LoaiThongBao", "TieuDe", "NoiDung", "ThoiGianGui", "DaDoc"
    ) VALUES (
      customer_account_id::integer, NULL, OLD."BookingID", 'booking_cancelled', 'Đặt lịch đã được hủy',
      ('Đặt lịch ' || OLD."MaBooking" || ' đã được hủy.'), now()::timestamp, false
    );
  END IF;

  RETURN OLD;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.notify_customer_order_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_account_id bigint;
  notification_title varchar(200);
  notification_body varchar(1000);
  notification_type varchar(50);
BEGIN
  IF NEW."BookingID" IS NOT NULL THEN
    SELECT private.account_id_for_booking(booking."BookingID", booking."KhachHangID")
    INTO customer_account_id
    FROM public."Booking" AS booking
    WHERE booking."BookingID" = NEW."BookingID";
  END IF;

  customer_account_id := COALESCE(
    customer_account_id,
    private.account_id_for_customer(NEW."KhachHangID")
  );

  IF customer_account_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    notification_title := 'Đơn hàng đã được tạo';
    notification_body := ('Cửa hàng đã tiếp nhận đồ và tạo đơn ' || NEW."MaDonHang" || '.');
    notification_type := 'order_created';
  ELSIF NEW."TrangThai" = 'Đã hủy' AND NEW."TrangThai" IS DISTINCT FROM OLD."TrangThai" THEN
    notification_title := 'Đơn hàng đã được hủy';
    notification_body := ('Đơn hàng ' || NEW."MaDonHang" || ' đã được hủy.');
    notification_type := 'order_cancelled';
  ELSIF NEW."TrangThai" IS DISTINCT FROM OLD."TrangThai" THEN
    notification_title := 'Đơn hàng đã cập nhật trạng thái';
    notification_body := ('Đơn hàng ' || NEW."MaDonHang" || ' hiện ở trạng thái ' || NEW."TrangThai" || '.');
    notification_type := 'order_status_updated';
  ELSE
    notification_title := 'Đơn hàng đã được cập nhật';
    notification_body := ('Thông tin đơn hàng ' || NEW."MaDonHang" || ' đã được cửa hàng cập nhật.');
    notification_type := 'order_updated';
  END IF;

  INSERT INTO public."ThongBao" (
    "TaiKhoanID", "DonHangID", "BookingID", "LoaiThongBao", "TieuDe", "NoiDung", "ThoiGianGui", "DaDoc"
  ) VALUES (
    customer_account_id::integer, NEW."DonHangID", NEW."BookingID", notification_type,
    notification_title, notification_body, now()::timestamp, false
  );

  RETURN NEW;
END;
$function$
;

COMMENT ON FUNCTION "private"."notify_customer_order_changed"() IS 'Notifies the booking owner when staff creates or updates its order.';

CREATE OR REPLACE FUNCTION private.notify_customers_new_promotion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW."TrangThai" = 'Hoạt động'
     AND NEW."NgayBatDau" <= CURRENT_DATE
     AND NEW."NgayKetThuc" >= CURRENT_DATE THEN
    INSERT INTO public."ThongBao" (
      "TaiKhoanID", "TieuDe", "NoiDung", "ThoiGianGui", "DaDoc", "DonHangID", "LoaiThongBao"
    )
    SELECT
      account."TaiKhoanID"::integer,
      'Có khuyến mãi mới'::varchar,
      ('Khuyến mãi ' || NEW."TenKhuyenMai" || ' (' || NEW."MaKhuyenMai" || ') đã sẵn sàng để sử dụng.')::varchar,
      now()::timestamp,
      false,
      NULL::integer,
      'promotion'::varchar
    FROM public."TaiKhoan" AS account
    JOIN public."KhachHang" AS customer
      ON customer."KhachHangID" = account."KhachHangID"
    WHERE account."TrangThai" = 'Hoạt động'
      AND customer."TrangThai" = 'Hoạt động';
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.record_legacy_order_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE points_awarded integer; action_name text; customer_balance integer; paid_total numeric; grand_total numeric;
BEGIN
 IF TG_OP='UPDATE' AND OLD."TrangThai" IS NOT DISTINCT FROM NEW."TrangThai" THEN RETURN NEW; END IF;
 INSERT INTO public."NhatKyHeThong"("TaiKhoanID","HanhDong","BangDuLieu","BanGhiID","DuLieuCu","DuLieuMoi","ThoiGian")
 VALUES(NULL,'Thay đổi trạng thái đơn hàng','DonHang',NEW."DonHangID",CASE WHEN TG_OP='UPDATE' THEN jsonb_build_object('TrangThai',OLD."TrangThai") END,jsonb_build_object('TrangThai',NEW."TrangThai"),now());
 IF NEW."TrangThai"='Đã hủy' THEN
  UPDATE public."HoaDon" SET "TrangThai"='Đã hủy' WHERE "DonHangID"=NEW."DonHangID";
  UPDATE public."GiaoNhan" SET "TrangThai"='Đã hủy' WHERE "DonHangID"=NEW."DonHangID";
 END IF;
 IF NEW."TrangThai"='Đã giao' THEN
  action_name:='Cộng điểm tích lũy đơn hàng';
  IF NOT EXISTS(SELECT 1 FROM public."NhatKyHeThong" WHERE "BangDuLieu"='DonHang' AND "BanGhiID"=NEW."DonHangID" AND "HanhDong"=action_name) THEN
   points_awarded:=floor(NEW."ThanhTien"/1000)::integer*100;
   INSERT INTO public."DiemTichLuy"("KhachHangID","DiemHienTai") VALUES(NEW."KhachHangID",0) ON CONFLICT("KhachHangID") DO NOTHING;
   SELECT "DiemHienTai" INTO customer_balance FROM public."DiemTichLuy" WHERE "KhachHangID"=NEW."KhachHangID" FOR UPDATE;
   UPDATE public."DiemTichLuy" SET "DiemHienTai"="DiemHienTai"+points_awarded,"NgayCapNhat"=now() WHERE "KhachHangID"=NEW."KhachHangID";
   INSERT INTO public."NhatKyHeThong"("HanhDong","BangDuLieu","BanGhiID","DuLieuCu","DuLieuMoi","ThoiGian")
   VALUES(action_name,'DonHang',NEW."DonHangID",jsonb_build_object('DiemHienTai',customer_balance),jsonb_build_object('DiemCong',points_awarded,'DiemHienTai',customer_balance+points_awarded,'ThanhTien',NEW."ThanhTien"),now());
  END IF;
  SELECT coalesce((SELECT "ThanhTien" FROM public."HoaDon" WHERE "DonHangID"=NEW."DonHangID" ORDER BY "HoaDonID" LIMIT 1),NEW."ThanhTien") INTO grand_total;
  SELECT coalesce(sum("SoTien"),0) INTO paid_total FROM public."ThanhToan" WHERE "DonHangID"=NEW."DonHangID" AND "TrangThai"='Thành công';
  IF grand_total>0 AND paid_total>=grand_total THEN
   UPDATE public."HoaDon" SET "TrangThai"='Đã thanh toán' WHERE "DonHangID"=NEW."DonHangID";
   UPDATE public."DonHang" SET "TrangThai"='Đã thanh toán',"NgayCapNhat"=now() WHERE "DonHangID"=NEW."DonHangID";
  END IF;
 ELSIF NEW."TrangThai"='Đã hủy' AND NEW."DiemSuDung">0 THEN
  action_name:='Hoàn điểm tích lũy đơn hàng';
  IF NOT EXISTS(SELECT 1 FROM public."NhatKyHeThong" WHERE "BangDuLieu"='DonHang' AND "BanGhiID"=NEW."DonHangID" AND "HanhDong"=action_name) THEN
   INSERT INTO public."DiemTichLuy"("KhachHangID","DiemHienTai") VALUES(NEW."KhachHangID",0) ON CONFLICT("KhachHangID") DO NOTHING;
   UPDATE public."DiemTichLuy" SET "DiemHienTai"="DiemHienTai"+NEW."DiemSuDung","NgayCapNhat"=now() WHERE "KhachHangID"=NEW."KhachHangID";
   INSERT INTO public."NhatKyHeThong"("HanhDong","BangDuLieu","BanGhiID","DuLieuMoi","ThoiGian") VALUES(action_name,'DonHang',NEW."DonHangID",jsonb_build_object('DiemHoan',NEW."DiemSuDung"),now());
  END IF;
 END IF;
 RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.record_order_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
	IF TG_OP = 'INSERT' THEN
		INSERT INTO public.donhang_trangthai (
			donhangid,
			taikhoanid,
			trangthaicu,
			trangthaimoi
		) VALUES (
			NEW.donhangid,
			(SELECT private.current_account_id()),
			NULL,
			NEW.trangthai
		);
	ELSIF OLD.trangthai IS DISTINCT FROM NEW.trangthai THEN
		INSERT INTO public.donhang_trangthai (
			donhangid,
			taikhoanid,
			trangthaicu,
			trangthaimoi
		) VALUES (
			NEW.donhangid,
			(SELECT private.current_account_id()),
			OLD.trangthai,
			NEW.trangthai
		);
	END IF;

	RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cancel_laundry_booking(p_bookingid bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_id bigint := (SELECT private.current_customer_id());
  booking_row public."Booking"%ROWTYPE;
  customer_name text;
BEGIN
  IF (SELECT auth.uid()) IS NULL OR customer_id IS NULL THEN
    RAISE EXCEPTION 'An active customer account is required';
  END IF;
  SELECT *
  INTO booking_row
  FROM public."Booking"
  WHERE "BookingID" = p_bookingid
    AND "KhachHangID" = customer_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found';
  END IF;
  IF booking_row."TrangThai"='DaHuy' THEN RETURN; END IF;
  IF booking_row."TrangThai" <> 'ChoTiepNhan'
     OR EXISTS (SELECT 1 FROM public."DonHang" WHERE "BookingID" = p_bookingid) THEN
    RAISE EXCEPTION 'Only pending bookings can be canceled';
  END IF;
  IF booking_row."DiemDaTru" AND booking_row."DiemSuDung">0 THEN
    UPDATE public."DiemTichLuy" SET "DiemHienTai"="DiemHienTai"+booking_row."DiemSuDung","NgayCapNhat"=now() WHERE "KhachHangID"=customer_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Reserved points ledger is missing'; END IF;
  END IF;
  UPDATE public."Booking"
  SET "DiemDaTru"=false,"DiemSuDung"=0,"TienGiamDoDiem"=0,"KhuyenMaiDaTru"=false,
      "TrangThai" = 'DaHuy',
      "NgayCapNhat" = now()
  WHERE "BookingID" = p_bookingid;
  IF booking_row."KhuyenMaiDaTru"
     AND booking_row."KhuyenMaiID" IS NOT NULL THEN
    UPDATE public."KhuyenMai"
    SET "SoLuongSuDung" = "SoLuongSuDung" + 1
    WHERE "KhuyenMaiID" = booking_row."KhuyenMaiID"
      AND "SoLuongSuDung" IS NOT NULL;
  END IF;
  SELECT "HoTen"
  INTO customer_name
  FROM public."KhachHang"
  WHERE "KhachHangID" = customer_id;
  INSERT INTO public."ThongBao" (
    "TaiKhoanID", "TieuDe", "NoiDung", "ThoiGianGui", "DaDoc", "DonHangID", "LoaiThongBao"
  )
  SELECT DISTINCT
    account_role."TaiKhoanID",
    'Yêu cầu đặt giặt bị hủy',
    'Khách hàng ' || coalesce(customer_name, 'Khách hàng') ||
      ' vừa hủy yêu cầu ' || booking_row."MaBooking" || '.',
    now(),
    false,
    NULL::integer,
    'booking_cancelled'
  FROM public."TaiKhoan_VaiTro" AS account_role
  JOIN public."VaiTro" AS role
    ON role."VaiTroID" = account_role."VaiTroID"
  JOIN public."TaiKhoan" AS account
    ON account."TaiKhoanID" = account_role."TaiKhoanID"
  WHERE role."TenVaiTro" IN ('Nhân viên', 'Quản lý', 'Chủ cửa hàng')
    AND role."TrangThai" = 'Hoạt động'
    AND account."TrangThai" = 'Hoạt động';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.complete_customer_profile(p_full_name text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
	current_user_id uuid := (SELECT auth.uid());
	verified_phone text;
	normalized_phone text;
	verified_email text;
	customer_name text := nullif(btrim(p_full_name), '');
	customer_id bigint;
	account_id bigint;
	account_count integer;
	customer_count integer;
	customer_role_id bigint;
BEGIN
	IF current_user_id IS NULL THEN
		RAISE EXCEPTION 'Authentication is required';
	END IF;

	SELECT users.phone, users.email
		INTO verified_phone, verified_email
	FROM auth.users AS users
	WHERE users.id = current_user_id
		AND users.phone_confirmed_at IS NOT NULL;

	IF verified_phone IS NULL THEN
		RAISE EXCEPTION 'A verified phone number is required';
	END IF;

	normalized_phone := private.normalize_phone(verified_phone);
	IF normalized_phone IS NULL THEN
		RAISE EXCEPTION 'A valid phone number is required';
	END IF;

	SELECT account.taikhoanid, account.khachhangid
		INTO account_id, customer_id
	FROM public.taikhoan AS account
	WHERE account.userauthid = current_user_id
		AND account.trangthai = 'Hoạt động';

	IF account_id IS NOT NULL THEN
		IF customer_id IS NOT NULL AND customer_name IS NOT NULL THEN
			UPDATE public.khachhang
			SET hoten = customer_name,
					email = coalesce(verified_email, email)
			WHERE khachhangid = customer_id;
		END IF;
		RETURN;
	END IF;

	SELECT count(*)::integer, min(account.taikhoanid)
		INTO account_count, account_id
	FROM public.taikhoan AS account
	WHERE private.normalize_phone(account.sodienthoai) = normalized_phone;

	IF account_count > 1 THEN
		RAISE EXCEPTION 'Multiple accounts use this phone number';
	END IF;

	IF account_id IS NOT NULL THEN
		SELECT account.khachhangid
			INTO customer_id
		FROM public.taikhoan AS account
		WHERE account.taikhoanid = account_id
		FOR UPDATE;

		IF customer_id IS NULL THEN
			RAISE EXCEPTION 'Staff accounts must be linked by a manager';
		END IF;

		UPDATE public.taikhoan
		SET userauthid = current_user_id,
			email = coalesce(verified_email, email)
		WHERE taikhoanid = account_id
			AND (userauthid IS NULL OR userauthid = current_user_id)
			AND trangthai = 'Hoạt động';

		IF NOT FOUND THEN
			RAISE EXCEPTION 'This customer account cannot be linked';
		END IF;

		IF customer_name IS NOT NULL THEN
			UPDATE public.khachhang
			SET hoten = customer_name,
				email = coalesce(verified_email, email)
			WHERE khachhangid = customer_id;
		END IF;
	ELSE
		SELECT count(*)::integer, min(customer.khachhangid)
			INTO customer_count, customer_id
		FROM public.khachhang AS customer
		WHERE private.normalize_phone(customer.sodienthoai) = normalized_phone;

		IF customer_count > 1 THEN
			RAISE EXCEPTION 'Multiple customer profiles use this phone number';
		END IF;

		IF customer_id IS NULL THEN
			IF customer_name IS NULL THEN
				RAISE EXCEPTION 'A full name is required to create a customer profile';
			END IF;

			INSERT INTO public.khachhang (hoten, sodienthoai, email)
			VALUES (customer_name, verified_phone, verified_email)
			RETURNING khachhangid INTO customer_id;
		ELSIF customer_name IS NOT NULL THEN
			UPDATE public.khachhang
			SET hoten = customer_name,
					email = coalesce(verified_email, email)
			WHERE khachhangid = customer_id;
		END IF;

		SELECT count(*)::integer, min(account.taikhoanid)
			INTO account_count, account_id
		FROM public.taikhoan AS account
		WHERE account.khachhangid = customer_id;

		IF account_count > 1 THEN
			RAISE EXCEPTION 'Multiple accounts are attached to this customer profile';
		END IF;

		IF account_id IS NULL THEN
			INSERT INTO public.taikhoan (
				tendangnhap,
				matkhau,
				email,
				sodienthoai,
				khachhangid,
				userauthid
			) VALUES (
				'auth-' || current_user_id::text,
				NULL,
				verified_email,
				verified_phone,
				customer_id,
				current_user_id
			)
			RETURNING taikhoanid INTO account_id;
		ELSE
			UPDATE public.taikhoan
			SET userauthid = current_user_id,
					email = coalesce(verified_email, email)
			WHERE taikhoanid = account_id
				AND userauthid IS NULL;

			IF NOT FOUND THEN
				RAISE EXCEPTION 'This customer profile is already linked to another account';
			END IF;
		END IF;
	END IF;

	IF customer_id IS NOT NULL THEN
		SELECT role.vaitroid INTO customer_role_id
		FROM public.vaitro AS role
		WHERE role.tenvaitro = 'Khách hàng'
			AND role.trangthai = 'Hoạt động';

		IF customer_role_id IS NULL THEN
			RAISE EXCEPTION 'The active customer role is not configured';
		END IF;

		INSERT INTO public.taikhoan_vaitro (taikhoanid, vaitroid)
		VALUES (account_id, customer_role_id)
		ON CONFLICT DO NOTHING;
	END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.complete_google_customer_profile(p_full_name text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  current_user_id uuid := (SELECT auth.uid());
  verified_email text;
  customer_name text;
  customer_id bigint;
  account_id bigint;
  customer_role_id bigint;
BEGIN
  IF current_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication is required';
  END IF;

  SELECT users.email,
    coalesce(
      nullif(btrim(p_full_name), ''),
      nullif(btrim(users.raw_user_meta_data ->> 'full_name'), ''),
      nullif(btrim(users.raw_user_meta_data ->> 'name'), ''),
      users.email
    )
  INTO verified_email, customer_name
  FROM auth.users AS users
  WHERE users.id = current_user_id;

  IF verified_email IS NULL THEN
    RAISE EXCEPTION 'A verified Google email is required';
  END IF;

  IF to_regclass('public.taikhoan') IS NOT NULL THEN
    SELECT account.taikhoanid, account.khachhangid
    INTO account_id, customer_id
    FROM public.taikhoan AS account
    WHERE account.userauthid = current_user_id
      AND account.trangthai = 'Hoạt động';

    IF account_id IS NOT NULL THEN
      UPDATE public.khachhang
      SET hoten = customer_name, email = verified_email
      WHERE khachhangid = customer_id;
      RETURN;
    END IF;

    SELECT customer.khachhangid INTO customer_id
    FROM public.khachhang AS customer
    WHERE lower(customer.email) = lower(verified_email)
    LIMIT 1;

    IF customer_id IS NULL THEN
      INSERT INTO public.khachhang (hoten, sodienthoai, email)
      VALUES (customer_name, NULL, verified_email)
      RETURNING khachhangid INTO customer_id;
    ELSE
      UPDATE public.khachhang
      SET hoten = customer_name, email = verified_email
      WHERE khachhangid = customer_id;
    END IF;

    INSERT INTO public.taikhoan (
      tendangnhap, matkhau, email, sodienthoai, khachhangid, userauthid
    ) VALUES (
      'auth-' || current_user_id::text, NULL, verified_email, NULL,
      customer_id, current_user_id
    )
    RETURNING taikhoanid INTO account_id;

    SELECT role.vaitroid INTO customer_role_id
    FROM public.vaitro AS role
    WHERE role.tenvaitro = 'Khách hàng'
      AND role.trangthai = 'Hoạt động';

    IF customer_role_id IS NULL THEN
      RAISE EXCEPTION 'The active customer role is not configured';
    END IF;

    INSERT INTO public.taikhoan_vaitro (taikhoanid, vaitroid)
    VALUES (account_id, customer_role_id)
    ON CONFLICT DO NOTHING;
  ELSE
    SELECT account."TaiKhoanID", account."KhachHangID"
    INTO account_id, customer_id
    FROM public."TaiKhoan" AS account
    WHERE account."UserAuthId" = current_user_id
      AND account."TrangThai" = 'Hoạt động';

    IF account_id IS NOT NULL THEN
      UPDATE public."KhachHang"
      SET "HoTen" = customer_name, "Email" = verified_email
      WHERE "KhachHangID" = customer_id;
      RETURN;
    END IF;

    SELECT customer."KhachHangID" INTO customer_id
    FROM public."KhachHang" AS customer
    WHERE lower(customer."Email") = lower(verified_email)
    LIMIT 1;

    IF customer_id IS NULL THEN
      INSERT INTO public."KhachHang" ("HoTen", "SoDienThoai", "Email")
      VALUES (customer_name, NULL, verified_email)
      RETURNING "KhachHangID" INTO customer_id;
    ELSE
      UPDATE public."KhachHang"
      SET "HoTen" = customer_name, "Email" = verified_email
      WHERE "KhachHangID" = customer_id;
    END IF;

    INSERT INTO public."TaiKhoan" (
      "TenDangNhap", "MatKhau", "Email", "SoDienThoai",
      "KhachHangID", "UserAuthId"
    ) VALUES (
      'auth-' || current_user_id::text, NULL, verified_email, NULL,
      customer_id, current_user_id
    )
    RETURNING "TaiKhoanID" INTO account_id;

    SELECT role."VaiTroID" INTO customer_role_id
    FROM public."VaiTro" AS role
    WHERE role."TenVaiTro" = 'Khách hàng'
      AND role."TrangThai" = 'Hoạt động';

    IF customer_role_id IS NULL THEN
      RAISE EXCEPTION 'The active customer role is not configured';
    END IF;

    INSERT INTO public."TaiKhoan_VaiTro" ("TaiKhoanID", "VaiTroID")
    VALUES (account_id, customer_role_id)
    ON CONFLICT DO NOTHING;
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.confirm_laundry_booking(p_bookingid bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE booking_row public."Booking"%ROWTYPE; order_row public."DonHang"%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(private.is_staff(),false) THEN RAISE EXCEPTION 'An active staff account is required'; END IF;
 SELECT * INTO booking_row FROM public."Booking" WHERE "BookingID"=p_bookingid FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Booking not found'; END IF;
 SELECT * INTO order_row FROM public."DonHang" WHERE "BookingID"=p_bookingid ORDER BY "DonHangID" LIMIT 1;
 IF FOUND THEN RETURN jsonb_build_object('donhangid',order_row."DonHangID",'madonhang',order_row."MaDonHang",'bookingid',p_bookingid,'trangthai',order_row."TrangThai",'tongtien',order_row."TongTien"); END IF;
 -- This existing RPC has no inspected items/condition argument. Never interpret
 -- a customer estimate (or an empty booking) as an inspection performed by staff.
 RAISE EXCEPTION 'Inspection required: use the Web inspection form to record actual measurements and item condition before creating an order' USING ERRCODE='22023';
END;
$function$
;

