CREATE OR REPLACE FUNCTION public.confirm_order_payment(p_thanhtoanid bigint, p_success boolean, p_ghichu text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE payment public."ThanhToan"%ROWTYPE; order_row public."DonHang"%ROWTYPE; invoice public."HoaDon"%ROWTYPE;
 order_id bigint; paid_total numeric; target_status text;
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(private.is_staff(),false) THEN RAISE EXCEPTION 'An active staff account is required'; END IF;
 IF p_success IS NULL THEN RAISE EXCEPTION 'A payment outcome is required'; END IF;
 SELECT "DonHangID" INTO order_id FROM public."ThanhToan" WHERE "ThanhToanID"=p_thanhtoanid;
 IF NOT FOUND THEN RAISE EXCEPTION 'Payment not found'; END IF;
 -- Every path locks order before payment/invoice: matches Web and request RPC.
 SELECT * INTO order_row FROM public."DonHang" WHERE "DonHangID"=order_id FOR UPDATE;
 SELECT * INTO payment FROM public."ThanhToan" WHERE "ThanhToanID"=p_thanhtoanid FOR UPDATE;
 IF payment."DonHangID"<>order_id THEN RAISE EXCEPTION 'Payment order changed'; END IF;
 target_status:=CASE WHEN p_success THEN 'Thành công' ELSE 'Thất bại' END;
 IF payment."TrangThai"=target_status THEN
  RETURN;
 END IF;
 IF payment."TrangThai"<>'Chờ thanh toán' THEN RAISE EXCEPTION 'Only pending payments can be confirmed'; END IF;
 IF order_row."TrangThai"='Đã hủy' THEN RAISE EXCEPTION 'Canceled orders cannot accept payments'; END IF;
 SELECT * INTO invoice FROM public."HoaDon" WHERE "DonHangID"=order_id ORDER BY "HoaDonID" LIMIT 1 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found'; END IF;
 SELECT coalesce(sum("SoTien"),0) INTO paid_total FROM public."ThanhToan" WHERE "DonHangID"=order_id AND "TrangThai"='Thành công';
 IF p_success AND (payment."SoTien"<=0 OR paid_total+payment."SoTien">invoice."ThanhTien") THEN RAISE EXCEPTION 'Payment exceeds the remaining invoice balance'; END IF;
 UPDATE public."ThanhToan" SET "TrangThai"=target_status,"ThoiGian"=now(),"GhiChu"=coalesce(nullif(btrim(p_ghichu),''),"GhiChu") WHERE "ThanhToanID"=p_thanhtoanid;
 IF p_success THEN
  paid_total:=paid_total+payment."SoTien";
  IF paid_total>=invoice."ThanhTien" THEN
   UPDATE public."HoaDon" SET "TrangThai"='Đã thanh toán' WHERE "HoaDonID"=invoice."HoaDonID";
   IF order_row."TrangThai"='Đã giao' THEN UPDATE public."DonHang" SET "TrangThai"='Đã thanh toán',"NgayCapNhat"=now() WHERE "DonHangID"=order_id; END IF;
  END IF;
 END IF;
 RETURN;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_current_account_id()
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT private.current_account_id()::integer;
$function$
;

CREATE OR REPLACE FUNCTION public.get_current_roles()
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  current_user_id uuid := (SELECT auth.uid());
  account_roles text[];
BEGIN
  IF current_user_id IS NULL THEN
    RETURN ARRAY[]::text[];
  END IF;

  IF to_regclass('public.taikhoan') IS NOT NULL THEN
    SELECT coalesce(array_agg(role.tenvaitro), ARRAY[]::text[])
    INTO account_roles
    FROM public.taikhoan AS account
    JOIN public.taikhoan_vaitro AS account_role
      ON account_role.taikhoanid = account.taikhoanid
    JOIN public.vaitro AS role ON role.vaitroid = account_role.vaitroid
    WHERE account.userauthid = current_user_id
      AND account.trangthai = 'Hoạt động'
      AND role.trangthai = 'Hoạt động';
  ELSE
    SELECT coalesce(array_agg(role."TenVaiTro"), ARRAY[]::text[])
    INTO account_roles
    FROM public."TaiKhoan" AS account
    JOIN public."TaiKhoan_VaiTro" AS account_role
      ON account_role."TaiKhoanID" = account."TaiKhoanID"
    JOIN public."VaiTro" AS role
      ON role."VaiTroID" = account_role."VaiTroID"
    WHERE account."UserAuthId" = current_user_id
      AND account."TrangThai" = 'Hoạt động'
      AND role."TrangThai" = 'Hoạt động';
  END IF;

  RETURN coalesce(account_roles, ARRAY[]::text[]);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_customer_loyalty()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_id bigint := (SELECT private.current_customer_id());
  current_points integer;
  active_vouchers jsonb;
BEGIN
  IF customer_id IS NULL THEN
    RAISE EXCEPTION 'An active customer account is required';
  END IF;

  SELECT coalesce(points."DiemHienTai", 0)
  INTO current_points
  FROM public."DiemTichLuy" AS points
  WHERE points."KhachHangID" = customer_id;

  SELECT coalesce(
    jsonb_agg(
      jsonb_build_object(
        'khuyenmaiid', promotion."KhuyenMaiID",
        'makhuyenmai', promotion."MaKhuyenMai",
        'tenkhuyenmai', promotion."TenKhuyenMai",
        'loaikhuyenmai', promotion."LoaiKhuyenMai",
        'giatrigiam', promotion."GiaTriGiam",
        'giatridontoithieu', promotion."GiaTriDonToiThieu",
        'mucgiamtoida', promotion."MucGiamToiDa",
        'dieukienapdung', promotion."DieuKienApDung"
      )
      ORDER BY promotion."NgayKetThuc"
    ),
    '[]'::jsonb
  )
  INTO active_vouchers
  FROM public."KhuyenMai" AS promotion
  WHERE promotion."TrangThai" = 'Hoạt động'
    AND promotion."NgayBatDau" <= current_date
    AND promotion."NgayKetThuc" >= current_date
    AND (
      promotion."SoLuongSuDung" IS NULL
      OR promotion."SoLuongSuDung" > 0
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public."Booking" AS booking
      WHERE booking."KhachHangID" = customer_id
        AND booking."KhuyenMaiID" = promotion."KhuyenMaiID"
        AND booking."TrangThai" <> 'DaHuy'
    );

  RETURN jsonb_build_object(
    'points', coalesce(current_points, 0),
    'vouchers', active_vouchers
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_laundry_order_status_history(p_donhangid bigint)
 RETURNS TABLE(trangthaicu text, trangthaimoi text, lydo text, thoigian timestamp without time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT
    event."DuLieuCu" ->> 'TrangThai',
    event."DuLieuMoi" ->> 'TrangThai',
    event."LyDo"::text,
    event."ThoiGian"
  FROM public."NhatKyHeThong" AS event
  WHERE (SELECT private.can_access_order(p_donhangid))
    AND event."BangDuLieu" = 'DonHang'
    AND event."BanGhiID" = p_donhangid
    AND event."HanhDong" = 'Thay đổi trạng thái đơn hàng'
  ORDER BY event."ThoiGian";
$function$
;

CREATE OR REPLACE FUNCTION public.get_staff_chat_inbox()
 RETURNS TABLE(customer_account_id integer, customer_name text, customer_avatar_url text, order_id integer, order_number text, last_message text, last_message_at timestamp without time zone, last_sender_account_id integer, unread_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  WITH conversations AS (
    SELECT DISTINCT ON (
      CASE WHEN sender."KhachHangID" IS NOT NULL THEN sender."TaiKhoanID" ELSE recipient."TaiKhoanID" END,
      m."DonHangID"
    )
      CASE WHEN sender."KhachHangID" IS NOT NULL THEN sender."TaiKhoanID" ELSE recipient."TaiKhoanID" END AS customer_account_id,
      m."DonHangID" AS order_id,
      m."NoiDung" AS last_message,
      m."ThoiGianGui" AS last_message_at,
      m."NguoiGuiID" AS last_sender_account_id
    FROM public."TinNhan" AS m
    JOIN public."TaiKhoan" AS sender ON sender."TaiKhoanID" = m."NguoiGuiID"
    JOIN public."TaiKhoan" AS recipient ON recipient."TaiKhoanID" = m."NguoiNhanID"
    WHERE sender."KhachHangID" IS NOT NULL OR recipient."KhachHangID" IS NOT NULL
    ORDER BY
      CASE WHEN sender."KhachHangID" IS NOT NULL THEN sender."TaiKhoanID" ELSE recipient."TaiKhoanID" END,
      m."DonHangID", m."ThoiGianGui" DESC, m."TinNhanID" DESC
  )
  SELECT c.customer_account_id,
    coalesce(k."HoTen", a."TenDangNhap", 'Khách hàng')::text,
    coalesce(k."AvatarUrl", a."AvatarURL")::text,
    c.order_id, d."MaDonHang"::text, c.last_message, c.last_message_at, c.last_sender_account_id,
    (
      SELECT count(*)
      FROM public."TinNhan" AS m
      JOIN public."TaiKhoan" AS sender ON sender."TaiKhoanID" = m."NguoiGuiID"
      WHERE sender."KhachHangID" IS NOT NULL
        AND m."NguoiGuiID" = c.customer_account_id
        AND m."DonHangID" IS NOT DISTINCT FROM c.order_id
        AND m."TrangThai" IN ('Đã gửi', 'Đã nhận')
    )
  FROM conversations AS c
  JOIN public."TaiKhoan" AS a ON a."TaiKhoanID" = c.customer_account_id
  LEFT JOIN public."KhachHang" AS k ON k."KhachHangID" = a."KhachHangID"
  LEFT JOIN public."DonHang" AS d ON d."DonHangID" = c.order_id
  WHERE auth.uid() IS NOT NULL AND private.is_messaging_staff()
  ORDER BY c.last_message_at DESC;
$function$
;

CREATE OR REPLACE FUNCTION public.get_support_chat_recipient()
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT CASE
    WHEN auth.uid() IS NOT NULL
      AND private.current_account_id() IS NOT NULL
      AND NOT private.is_messaging_staff()
    THEN private.default_support_account_id()
    ELSE NULL
  END;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_chat_thread_read(p_peer_account_id integer, p_order_id integer DEFAULT NULL::integer)
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  WITH customer_accounts AS (
    SELECT a."TaiKhoanID" FROM public."TaiKhoan" AS a
    WHERE a."KhachHangID" = (SELECT private.current_customer_id())
  ),
  updated AS (
    UPDATE public."TinNhan" AS m SET "TrangThai" = 'Đã đọc'
    WHERE m."DonHangID" IS NOT DISTINCT FROM p_order_id
      AND m."TrangThai" IN ('Đã gửi', 'Đã nhận')
      AND (
        (NOT private.is_messaging_staff()
          AND m."NguoiNhanID" IN (SELECT "TaiKhoanID" FROM customer_accounts)
          AND (p_order_id IS NULL OR (SELECT private.can_access_order(p_order_id::bigint)))
        )
        OR (private.is_messaging_staff()
          AND m."NguoiGuiID" = p_peer_account_id
          AND m."NguoiNhanID" IN (
            SELECT a."TaiKhoanID" FROM public."TaiKhoan" AS a
            WHERE a."NhanVienID" IS NOT NULL AND EXISTS (
              SELECT 1 FROM public."TaiKhoan_VaiTro" AS av
              JOIN public."VaiTro" AS r ON r."VaiTroID" = av."VaiTroID"
              WHERE av."TaiKhoanID" = a."TaiKhoanID"
                AND r."TrangThai" = 'Hoạt động'
                AND (r."TenVaiTro" IN ('Nhân viên','Chủ cửa hàng') OR r."TenVaiTro" LIKE 'Quản lý%')
            )
          )
          AND EXISTS (
            SELECT 1 FROM public."TaiKhoan" AS customer
            WHERE customer."TaiKhoanID" = p_peer_account_id
              AND customer."KhachHangID" IS NOT NULL
          ))
      )
    RETURNING m."TinNhanID"
  ),
  synced_notifications AS (
    UPDATE public."ThongBao" AS n SET "DaDoc" = true
    WHERE NOT private.is_messaging_staff()
      AND n."LoaiThongBao" = 'new_message'
      AND n."TaiKhoanID" IN (SELECT "TaiKhoanID" FROM customer_accounts)
      AND n."TinNhanID" IN (
        SELECT m."TinNhanID" FROM public."TinNhan" AS m
        WHERE m."DonHangID" IS NOT DISTINCT FROM p_order_id
          AND m."NguoiNhanID" IN (SELECT "TaiKhoanID" FROM customer_accounts)
          AND (m."TrangThai" = 'Đã đọc' OR m."TinNhanID" IN (SELECT "TinNhanID" FROM updated))
      )
    RETURNING n."ThongBaoID"
  )
  SELECT count(*)::integer FROM updated;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_notifications_read(p_notification_ids bigint[] DEFAULT NULL::bigint[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  current_account_id bigint := (SELECT private.current_account_id());
  updated_count integer;
BEGIN
  IF (SELECT auth.uid()) IS NULL OR current_account_id IS NULL THEN
    RAISE EXCEPTION 'An active account is required';
  END IF;

  UPDATE public."ThongBao"
  SET "DaDoc" = true
  WHERE "TaiKhoanID" = current_account_id
    AND "DaDoc" = false
    AND (
      p_notification_ids IS NULL
      OR "ThongBaoID" = ANY (p_notification_ids)
    );

  GET DIAGNOSTICS updated_count = ROW_COUNT;
  RETURN updated_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_customer_of_store_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  recipient_customer_id integer;
  sender_is_staff boolean;
  recipient_is_staff boolean;
BEGIN
  SELECT a."KhachHangID" INTO recipient_customer_id
  FROM public."TaiKhoan" AS a
  WHERE a."TaiKhoanID" = NEW."NguoiNhanID" AND a."TrangThai" = 'Hoạt động';

  SELECT EXISTS (
    SELECT 1 FROM public."TaiKhoan" AS a
    JOIN public."TaiKhoan_VaiTro" AS av ON av."TaiKhoanID" = a."TaiKhoanID"
    JOIN public."VaiTro" AS r ON r."VaiTroID" = av."VaiTroID"
    WHERE a."TaiKhoanID" = NEW."NguoiGuiID"
      AND a."NhanVienID" IS NOT NULL AND a."TrangThai" = 'Hoạt động'
      AND r."TrangThai" = 'Hoạt động'
      AND (r."TenVaiTro" IN ('Nhân viên', 'Chủ cửa hàng') OR r."TenVaiTro" LIKE 'Quản lý%')
  ) INTO sender_is_staff;

  IF recipient_customer_id IS NOT NULL THEN
    INSERT INTO public."ThongBao" (
      "TaiKhoanID", "DonHangID", "TinNhanID", "LoaiThongBao",
      "TieuDe", "NoiDung", "ThoiGianGui", "DaDoc"
    )
    SELECT customer_account."TaiKhoanID", NEW."DonHangID", NEW."TinNhanID",
      'new_message',
      CASE WHEN sender_is_staff THEN 'Tin nhắn mới từ cửa hàng' ELSE 'Tin nhắn mới' END,
      left(CASE WHEN sender_is_staff THEN 'Cửa hàng: ' ELSE 'Tin nhắn: ' END || NEW."NoiDung", 1000),
      timezone('utc', now())::timestamp, false
    FROM public."TaiKhoan" AS customer_account
    WHERE customer_account."KhachHangID" = recipient_customer_id
      AND customer_account."TrangThai" = 'Hoạt động'
      AND customer_account."TaiKhoanID" <> NEW."NguoiGuiID"
      AND (NEW."DonHangID" IS NULL OR EXISTS (
        SELECT 1 FROM public."DonHang" AS d
        WHERE d."DonHangID" = NEW."DonHangID" AND d."KhachHangID" = recipient_customer_id
      ))
      AND NOT EXISTS (
        SELECT 1 FROM public."ThongBao" AS existing
        WHERE existing."TaiKhoanID" = customer_account."TaiKhoanID"
          AND existing."TinNhanID" = NEW."TinNhanID"
          AND existing."LoaiThongBao" = 'new_message'
      );
  ELSE
    SELECT EXISTS (
      SELECT 1 FROM public."TaiKhoan" AS a
      JOIN public."TaiKhoan_VaiTro" AS av ON av."TaiKhoanID" = a."TaiKhoanID"
      JOIN public."VaiTro" AS r ON r."VaiTroID" = av."VaiTroID"
      WHERE a."TaiKhoanID" = NEW."NguoiNhanID"
        AND a."NhanVienID" IS NOT NULL AND a."TrangThai" = 'Hoạt động'
        AND r."TrangThai" = 'Hoạt động'
        AND (r."TenVaiTro" IN ('Nhân viên', 'Chủ cửa hàng') OR r."TenVaiTro" LIKE 'Quản lý%')
    ) INTO recipient_is_staff;
    IF recipient_is_staff THEN
      INSERT INTO public."ThongBao" (
        "TaiKhoanID", "DonHangID", "TinNhanID", "LoaiThongBao",
        "TieuDe", "NoiDung", "ThoiGianGui", "DaDoc"
      ) VALUES (
        NEW."NguoiNhanID", NEW."DonHangID", NEW."TinNhanID", 'new_message',
        'Tin nhắn mới từ khách hàng', left('Khách hàng: ' || NEW."NoiDung", 1000),
        timezone('utc', now())::timestamp, false
      );
    END IF;
  END IF;
  RETURN NEW;
END
$function$
;

CREATE OR REPLACE FUNCTION public.notify_staff_new_booking(p_bookingid bigint, p_booking_number text, p_customer_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  INSERT INTO public."ThongBao" (
    "TaiKhoanID", "TieuDe", "NoiDung", "ThoiGianGui", "DaDoc", "DonHangID", "LoaiThongBao"
  )
  SELECT DISTINCT
    account_role."TaiKhoanID"::integer,
    'Có yêu cầu đặt giặt mới'::varchar,
    ('Khách hàng ' || coalesce(nullif(btrim(p_customer_name), ''), 'Khách hàng') ||
      ' vừa gửi yêu cầu ' || coalesce(nullif(btrim(p_booking_number), ''), '#' || p_bookingid::text) || '.')::varchar,
    now()::timestamp,
    false,
    NULL::integer,
    'new_booking'::varchar
  FROM public."TaiKhoan_VaiTro" AS account_role
  JOIN public."VaiTro" AS role
    ON role."VaiTroID" = account_role."VaiTroID"
  JOIN public."TaiKhoan" AS account
    ON account."TaiKhoanID" = account_role."TaiKhoanID"
  WHERE role."TenVaiTro" IN ('Nhân viên', 'Quản lý', 'Chủ cửa hàng')
    AND role."TrangThai" = 'Hoạt động'
    AND account."TrangThai" = 'Hoạt động'
    AND NOT EXISTS (
      SELECT 1
      FROM public."ThongBao" AS notification
      WHERE notification."TaiKhoanID" = account_role."TaiKhoanID"
        AND notification."LoaiThongBao" = 'new_booking'
        AND notification."DonHangID" IS NULL
        AND notification."NoiDung" LIKE '%' || coalesce(nullif(btrim(p_booking_number), ''), '#' || p_bookingid::text) || '%'
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.request_order_payment(p_donhangid bigint, p_phuongthuc text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    customer_id bigint :=
        (SELECT private.current_customer_id());
    order_record public."DonHang"%ROWTYPE;
    invoice public."HoaDon"%ROWTYPE;
    existing_payment public."ThanhToan"%ROWTYPE;
    amount_due numeric(18,2);
    payment_id bigint;
BEGIN
    -- =====================================================
    -- 1. Kiểm tra khách hàng
    -- =====================================================
    IF (SELECT auth.uid()) IS NULL
       OR customer_id IS NULL THEN
        RAISE EXCEPTION
            'An active customer account is required';
    END IF;
    -- =====================================================
    -- 2. Kiểm tra phương thức thanh toán
    -- =====================================================
    IF p_phuongthuc NOT IN (
        'Tiền mặt',
        'Chuyển khoản'
    ) THEN
        RAISE EXCEPTION
            'Unsupported payment method';
    END IF;
    -- =====================================================
    -- 3. Kiểm tra Idempotency
    -- =====================================================
    IF p_idempotency_key IS NULL THEN
        RAISE EXCEPTION
            'An idempotency key is required';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            p_idempotency_key::text,
            0
        )
    );
    -- =====================================================
    -- 4. Kiểm tra Payment đã tạo trước đó
    -- =====================================================
    SELECT *
    INTO existing_payment
    FROM public."ThanhToan"
    WHERE "MaGiaoDich" = 'RPC-'||p_idempotency_key::text;
    IF FOUND THEN
        IF existing_payment."DonHangID"<>p_donhangid OR existing_payment."PhuongThuc" IS DISTINCT FROM p_phuongthuc THEN RAISE EXCEPTION 'Idempotency key is already in use'; END IF;
        IF NOT EXISTS (
            SELECT 1
            FROM public."DonHang" AS order_row
            WHERE order_row."DonHangID" =
                  existing_payment."DonHangID"
              AND order_row."KhachHangID" =
                  customer_id
        ) THEN
            RAISE EXCEPTION
                'Idempotency key is already in use';
        END IF;
        RETURN jsonb_build_object(
            'thanhtoanid',
            existing_payment."ThanhToanID",
            'sotien',
            existing_payment."SoTien",
            'trangthai',
            existing_payment."TrangThai",
            'phuongthuc',
            existing_payment."PhuongThuc"
        );
    END IF;
    -- =====================================================
    -- 5. Lấy và khóa Order
    -- =====================================================
    SELECT *
    INTO order_record
    FROM public."DonHang"
    WHERE "DonHangID" = p_donhangid
      AND "KhachHangID" = customer_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Order not found';
    END IF;
    -- Chỉ thanh toán sau khi giao
    IF order_record."TrangThai" NOT IN (
        'Đã giao',
        'Đã thanh toán'
    ) THEN
        RAISE EXCEPTION
            'Payment is available after the order is delivered';
    END IF;
    -- =====================================================
    -- 6. Lấy Invoice
    -- =====================================================
    SELECT *
    INTO invoice
    FROM public."HoaDon"
    WHERE "DonHangID" = p_donhangid
    FOR UPDATE;
    IF NOT FOUND
       OR invoice."TrangThai" <> 'Chưa thanh toán' THEN
        RAISE EXCEPTION
            'No unpaid invoice is available';
    END IF;
    -- =====================================================
    -- 7. Tính số tiền còn phải trả
    -- =====================================================
    SELECT
        greatest(
            invoice."ThanhTien"
            -
            coalesce(
                sum(payment."SoTien")
                FILTER (
                    WHERE payment."TrangThai" =
                          'Thành công'
                ),
                0
            ),
            0
        )
    INTO amount_due
    FROM public."ThanhToan" AS payment
    WHERE payment."DonHangID" =
          p_donhangid;
    IF amount_due <= 0 THEN
        RAISE EXCEPTION
            'The invoice has no remaining balance';
    END IF;
    -- =====================================================
    -- 8. Tạo Payment
    -- =====================================================
    INSERT INTO public."ThanhToan" (
        "DonHangID",
        "PhuongThuc",
        "SoTien",
        "TrangThai",
        "MaGiaoDich",
        "GhiChu"
    )
    VALUES (
        p_donhangid,
        p_phuongthuc,
        amount_due,
        'Chờ thanh toán',
        'RPC-'||p_idempotency_key::text,
        CASE
            WHEN p_phuongthuc = 'Chuyển khoản'
            THEN
                'Khách chọn chuyển khoản; chờ cửa hàng đối soát.'
            ELSE
                'Khách chọn tiền mặt; chờ cửa hàng thu tiền.'
        END
    )
    RETURNING "ThanhToanID"
    INTO payment_id;
    -- =====================================================
    -- 9. Trả kết quả
    -- =====================================================
    RETURN jsonb_build_object(
        'thanhtoanid',
        payment_id,
        'sotien',
        amount_due,
        'trangthai',
        'Chờ thanh toán',
        'phuongthuc',
        p_phuongthuc
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.save_customer_address(p_diachiid bigint, p_tennguoinhan text, p_sodienthoai text, p_diachi text, p_ghichu text, p_macdinh boolean)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
	customer_id bigint := (SELECT private.current_customer_id());
	address_id bigint;
BEGIN
	IF (SELECT auth.uid()) IS NULL OR customer_id IS NULL THEN
		RAISE EXCEPTION 'An active customer account is required';
	END IF;
	IF nullif(btrim(p_diachi), '') IS NULL THEN
		RAISE EXCEPTION 'Address is required';
	END IF;

	IF p_diachiid IS NULL THEN
		INSERT INTO public.khachhang_diachi (
			khachhangid,
			tennguoinhan,
			sodienthoai,
			diachi,
			ghichu,
			macdinh
		) VALUES (
			customer_id,
			nullif(btrim(p_tennguoinhan), ''),
			nullif(btrim(p_sodienthoai), ''),
			btrim(p_diachi),
			nullif(btrim(p_ghichu), ''),
			false
		) RETURNING diachiid INTO address_id;
	ELSE
		UPDATE public.khachhang_diachi
		SET tennguoinhan = nullif(btrim(p_tennguoinhan), ''),
			sodienthoai = nullif(btrim(p_sodienthoai), ''),
			diachi = btrim(p_diachi),
			ghichu = nullif(btrim(p_ghichu), '')
		WHERE diachiid = p_diachiid
			AND khachhangid = customer_id
		RETURNING diachiid INTO address_id;

		IF address_id IS NULL THEN
			RAISE EXCEPTION 'Address not found';
		END IF;
	END IF;

	IF coalesce(p_macdinh, false) THEN
		UPDATE public.khachhang_diachi
		SET macdinh = false
		WHERE khachhangid = customer_id
			AND macdinh;

		UPDATE public.khachhang_diachi
		SET macdinh = true
		WHERE diachiid = address_id
			AND khachhangid = customer_id;
	END IF;

	RETURN address_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.send_chat_message(p_recipient_account_id integer, p_content text, p_order_id integer DEFAULT NULL::integer)
 RETURNS SETOF "TinNhan"
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  INSERT INTO public."TinNhan"
    ("NguoiGuiID", "NguoiNhanID", "DonHangID", "NoiDung", "ThoiGianGui", "TrangThai")
  SELECT sender."TaiKhoanID", recipient."TaiKhoanID", p_order_id, btrim(p_content),
    timezone('utc', now())::timestamp, 'Đã gửi'
  FROM public."TaiKhoan" AS sender
  JOIN public."TaiKhoan" AS recipient ON recipient."TaiKhoanID" = p_recipient_account_id
  WHERE auth.uid() IS NOT NULL
    AND sender."TaiKhoanID" = private.current_account_id()
    AND sender."TrangThai" = 'Hoạt động'
    AND recipient."TrangThai" = 'Hoạt động'
    AND nullif(btrim(p_content), '') IS NOT NULL
    AND char_length(btrim(p_content)) <= 1000
    AND (
      (
        NOT private.is_messaging_staff()
        AND sender."KhachHangID" IS NOT NULL
        AND recipient."TaiKhoanID" = private.default_support_account_id()
        AND (
          p_order_id IS NULL
          OR (
            (SELECT private.can_access_order(p_order_id::bigint))
            AND EXISTS (
              SELECT 1 FROM public."DonHang" d
              WHERE d."DonHangID" = p_order_id
                AND d."KhachHangID" = sender."KhachHangID"
            )
          )
        )
      )
      OR (
        private.is_messaging_staff()
        AND recipient."KhachHangID" IS NOT NULL
        AND (
          p_order_id IS NULL
          OR EXISTS (
            SELECT 1 FROM public."DonHang" d
            WHERE d."DonHangID" = p_order_id
              AND d."KhachHangID" = recipient."KhachHangID"
          )
        )
      )
    )
  RETURNING *;
$function$
;

CREATE OR REPLACE FUNCTION public.set_booking_promotion(p_bookingid bigint, p_makhuyenmai text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_id bigint := (SELECT private.current_customer_id());
  booking_row public."Booking"%ROWTYPE;
  promotion public."KhuyenMai"%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL OR customer_id IS NULL THEN
    RAISE EXCEPTION 'An active customer account is required';
  END IF;

  SELECT *
  INTO booking_row
  FROM public."Booking"
  WHERE "BookingID" = p_bookingid
    AND "KhachHangID" = customer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found';
  END IF;

  SELECT *
  INTO promotion
  FROM public."KhuyenMai"
  WHERE upper("MaKhuyenMai") = upper(btrim(p_makhuyenmai))
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Promotion code does not exist';
  END IF;

  IF booking_row."KhuyenMaiID" IS NOT NULL THEN
    IF booking_row."KhuyenMaiID" = promotion."KhuyenMaiID" THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'A promotion has already been reserved for this booking';
  END IF;

  IF booking_row."TrangThai" <> 'ChoTiepNhan'
     OR EXISTS (
       SELECT 1
       FROM public."DonHang"
       WHERE "BookingID" = p_bookingid
     ) THEN
    RAISE EXCEPTION 'Only pending bookings can use a promotion';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public."Booking" AS existing_booking
    WHERE existing_booking."KhachHangID" = customer_id
      AND existing_booking."KhuyenMaiID" = promotion."KhuyenMaiID"
      AND existing_booking."TrangThai" <> 'DaHuy'
  ) THEN
    RAISE EXCEPTION 'Promotion has already been used by this customer';
  END IF;

  IF promotion."TrangThai" <> 'Hoạt động'
     OR promotion."NgayBatDau" > current_date
     OR promotion."NgayKetThuc" < current_date
     OR (
       promotion."SoLuongSuDung" IS NOT NULL
       AND promotion."SoLuongSuDung" <= 0
     ) THEN
    RAISE EXCEPTION 'Promotion code is invalid, expired, or unavailable';
  END IF;

  IF promotion."SoLuongSuDung" IS NOT NULL THEN
    UPDATE public."KhuyenMai"
    SET "SoLuongSuDung" = "SoLuongSuDung" - 1
    WHERE "KhuyenMaiID" = promotion."KhuyenMaiID"
      AND "SoLuongSuDung" > 0;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Promotion code is no longer available';
    END IF;
  END IF;

  UPDATE public."Booking"
  SET "KhuyenMaiID" = promotion."KhuyenMaiID",
      "KhuyenMaiDaTru" = promotion."SoLuongSuDung" IS NOT NULL
  WHERE "BookingID" = p_bookingid;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_laundry_booking_request(p_items jsonb, p_hinhthucnhando text, p_diachinhan text, p_ngayhen date, p_giohen time without time zone, p_ghichu text, p_idempotency_key uuid, p_use_points boolean, p_makhuyenmai text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  booking_result jsonb;
BEGIN
  IF p_items IS NULL THEN
    booking_result := public.submit_laundry_booking_without_details(
      p_hinhthucnhando,
      p_diachinhan,
      p_ngayhen,
      p_giohen,
      p_ghichu,
      p_idempotency_key
    );
  ELSIF coalesce(p_use_points, false) THEN
    booking_result := public.submit_laundry_order_cart_with_points(
      p_items,
      p_hinhthucnhando,
      p_diachinhan,
      p_ngayhen,
      p_giohen,
      p_ghichu,
      p_idempotency_key,
      true
    );
  ELSE
    booking_result := public.submit_laundry_order_cart(
      p_items,
      p_hinhthucnhando,
      p_diachinhan,
      p_ngayhen,
      p_giohen,
      p_ghichu,
      p_idempotency_key
    );
  END IF;

  IF nullif(btrim(p_makhuyenmai), '') IS NOT NULL THEN
    PERFORM public.set_booking_promotion(
      (booking_result->>'bookingid')::bigint,
      p_makhuyenmai
    );
  END IF;

  RETURN booking_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_laundry_booking_request(p_items jsonb, p_hinhthucnhando text, p_diachinhan text, p_ngayhen date, p_giohen time without time zone, p_ghichu text, p_idempotency_key uuid, p_use_points boolean, p_phuongthucthanhtoan text, p_makhuyenmai text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  booking_result jsonb;
  customer_id bigint := (SELECT private.current_customer_id());
BEGIN
  IF p_phuongthucthanhtoan IS NULL
     OR p_phuongthucthanhtoan NOT IN ('Tiền mặt', 'Chuyển khoản') THEN
    RAISE EXCEPTION 'Unsupported payment method';
  END IF;

  booking_result := public.submit_laundry_booking_request(
    p_items => p_items,
    p_hinhthucnhando => p_hinhthucnhando,
    p_diachinhan => p_diachinhan,
    p_ngayhen => p_ngayhen,
    p_giohen => p_giohen,
    p_ghichu => p_ghichu,
    p_idempotency_key => p_idempotency_key,
    p_use_points => p_use_points,
    p_makhuyenmai => p_makhuyenmai
  );

  UPDATE public."Booking"
  SET "PhuongThucThanhToan" = p_phuongthucthanhtoan
  WHERE "BookingID" = (booking_result->>'bookingid')::bigint
    AND "KhachHangID" = customer_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found for current customer';
  END IF;

  RETURN booking_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_laundry_booking_with_delivery(p_items jsonb, p_hinhthucnhando text, p_hinhthucgiaodo text, p_diachinhan text, p_ngayhen date, p_giohen time without time zone, p_ghichu text, p_idempotency_key uuid, p_use_points boolean, p_phuongthucthanhtoan text, p_makhuyenmai text DEFAULT NULL::text, p_diachigiao text DEFAULT NULL::text, p_delivery_fee_quote_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  booking_result jsonb;
  customer_id bigint := (SELECT private.current_customer_id());
  current_user_id uuid := (SELECT auth.uid());
  booking_id bigint;
  quote_row public.delivery_fee_quotes%ROWTYPE;
  pickup_distance integer := 0;
  delivery_distance integer := 0;
  pickup_fee numeric(12, 2) := 0;
  delivery_fee numeric(12, 2) := 0;
  total_delivery_fee numeric(12, 2) := 0;
  pickup_address text;
  delivery_address text;
BEGIN
  IF current_user_id IS NULL OR customer_id IS NULL THEN
    RAISE EXCEPTION 'An active customer account is required';
  END IF;
  IF p_hinhthucnhando NOT IN ('Tại cửa hàng', 'Tại nhà')
     OR p_hinhthucgiaodo NOT IN ('Tại cửa hàng', 'Tại nhà') THEN
    RAISE EXCEPTION 'Unsupported delivery method';
  END IF;
  IF p_hinhthucnhando = 'Tại nhà'
     AND nullif(btrim(COALESCE(p_diachinhan, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Pickup address is required';
  END IF;
  IF p_hinhthucgiaodo = 'Tại nhà'
     AND nullif(btrim(COALESCE(p_diachigiao, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Delivery address is required';
  END IF;

  pickup_address := CASE WHEN p_hinhthucnhando = 'Tại nhà'
    THEN nullif(btrim(p_diachinhan), '') ELSE NULL END;
  delivery_address := CASE WHEN p_hinhthucgiaodo = 'Tại nhà'
    THEN nullif(btrim(p_diachigiao), '') ELSE NULL END;

  IF pickup_address IS NOT NULL OR delivery_address IS NOT NULL THEN
    IF p_delivery_fee_quote_id IS NULL THEN
      RAISE EXCEPTION 'A current delivery fee quote is required';
    END IF;

    SELECT * INTO quote_row
    FROM public.delivery_fee_quotes
    WHERE id = p_delivery_fee_quote_id
    FOR UPDATE;

    IF NOT FOUND
       OR quote_row.auth_user_id <> current_user_id
       OR (
         pickup_address IS NULL
         AND quote_row.pickup_address_hash IS NOT NULL
       )
       OR (
         pickup_address IS NOT NULL
         AND quote_row.pickup_address_hash IS DISTINCT FROM
           encode(extensions.digest(convert_to(btrim(pickup_address), 'UTF8'), 'sha256'), 'hex')
       )
       OR (
         delivery_address IS NULL
         AND quote_row.delivery_address_hash IS NOT NULL
       )
       OR (
         delivery_address IS NOT NULL
         AND quote_row.delivery_address_hash IS DISTINCT FROM
           encode(extensions.digest(convert_to(btrim(delivery_address), 'UTF8'), 'sha256'), 'hex')
       )
       OR (
         quote_row.expires_at <= now()
         AND quote_row.consumed_booking_id IS NULL
       ) THEN
      RAISE EXCEPTION 'Delivery fee quote is invalid or expired';
    END IF;

    IF quote_row.consumed_booking_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public."Booking"
      WHERE "BookingID" = quote_row.consumed_booking_id
        AND "KhachHangID" = customer_id
        AND "IdempotencyKey" = p_idempotency_key
    ) THEN
      RAISE EXCEPTION 'Delivery fee quote has already been used';
    END IF;

    pickup_distance := CASE WHEN pickup_address IS NOT NULL
      THEN quote_row.pickup_distance_meters ELSE 0 END;
    delivery_distance := CASE WHEN delivery_address IS NOT NULL
      THEN quote_row.delivery_distance_meters ELSE 0 END;

    -- First 3,000 meters are free on each leg. Each additional meter costs
    -- 5 VND; round the fee up to the next 1,000 VND.
    pickup_fee := ceil(greatest(pickup_distance - 3000, 0)::numeric * 5 / 1000) * 1000;
    delivery_fee := ceil(greatest(delivery_distance - 3000, 0)::numeric * 5 / 1000) * 1000;
  ELSIF p_delivery_fee_quote_id IS NOT NULL THEN
    RAISE EXCEPTION 'A delivery fee quote was supplied without a home delivery leg';
  END IF;

  booking_result := public.submit_laundry_booking_request(
    p_items => p_items,
    p_hinhthucnhando => p_hinhthucnhando,
    p_diachinhan => p_diachinhan,
    p_ngayhen => p_ngayhen,
    p_giohen => p_giohen,
    p_ghichu => p_ghichu,
    p_idempotency_key => p_idempotency_key,
    p_use_points => p_use_points,
    p_phuongthucthanhtoan => p_phuongthucthanhtoan,
    p_makhuyenmai => p_makhuyenmai
  );

  booking_id := (booking_result->>'bookingid')::bigint;
  IF p_delivery_fee_quote_id IS NOT NULL
     AND quote_row.consumed_booking_id IS NOT NULL
     AND quote_row.consumed_booking_id <> booking_id THEN
    RAISE EXCEPTION 'Delivery fee quote has already been used';
  END IF;
  total_delivery_fee := pickup_fee + delivery_fee;

  UPDATE public."Booking"
  SET "HinhThucGiaoDo" = p_hinhthucgiaodo,
      "DiaChiGiao" = delivery_address,
      "PickupDistanceMeters" = pickup_distance,
      "PickupDeliveryFee" = pickup_fee,
      "DeliveryDistanceMeters" = delivery_distance,
      "DeliveryFee" = delivery_fee
  WHERE "BookingID" = booking_id
    AND "KhachHangID" = customer_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found for current customer';
  END IF;

  IF p_delivery_fee_quote_id IS NOT NULL THEN
    UPDATE public.delivery_fee_quotes
    SET consumed_booking_id = booking_id
    WHERE id = p_delivery_fee_quote_id;
  END IF;

  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'Booking'
      AND column_name = 'HinhThucTraDo'
  ) THEN
    EXECUTE 'UPDATE public."Booking" SET "HinhThucTraDo" = $1 WHERE "BookingID" = $2'
      USING p_hinhthucgiaodo, booking_id;
  END IF;
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'Booking'
      AND column_name = 'DiaChiTra'
  ) THEN
    EXECUTE 'UPDATE public."Booking" SET "DiaChiTra" = $1 WHERE "BookingID" = $2'
      USING delivery_address, booking_id;
  END IF;

  RETURN booking_result || jsonb_build_object(
    'pickupdistancemeters', pickup_distance,
    'pickupdeliveryfee', pickup_fee,
    'deliverydistancemeters', delivery_distance,
    'deliveryfee', delivery_fee,
    'totaldeliveryfee', total_delivery_fee
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_laundry_booking_without_details(p_hinhthucnhando text, p_diachinhan text, p_ngayhen date, p_giohen time without time zone, p_ghichu text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_id bigint := (SELECT private.current_customer_id());
  existing_booking record;
  booking_id bigint;
  booking_number text;
BEGIN
  IF customer_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF p_idempotency_key IS NULL THEN RAISE EXCEPTION 'An idempotency key is required'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_idempotency_key::text,0));
  IF p_hinhthucnhando IS NULL OR p_hinhthucnhando NOT IN ('Tại cửa hàng','Tại nhà') THEN RAISE EXCEPTION 'Unsupported pickup method'; END IF;
  IF p_hinhthucnhando='Tại nhà' AND nullif(btrim(p_diachinhan),'') IS NULL THEN RAISE EXCEPTION 'A pickup address is required'; END IF;
  IF p_ngayhen IS NULL OR p_ngayhen<current_date OR p_giohen IS NULL THEN RAISE EXCEPTION 'A current pickup appointment is required'; END IF;
  SELECT * INTO existing_booking
  FROM public."Booking"
  WHERE "IdempotencyKey" = p_idempotency_key
    AND "KhachHangID" = customer_id;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'bookingid', existing_booking."BookingID",
      'mabooking', existing_booking."MaBooking",
      'trangthai', existing_booking."TrangThai",
      'thanhtien', 0,
      'itemcount', 0
    );
  END IF;
  IF EXISTS(SELECT 1 FROM public."Booking" WHERE "IdempotencyKey"=p_idempotency_key) THEN RAISE EXCEPTION 'Idempotency key is already in use'; END IF;
  booking_number := 'BK-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISS') ||
    '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 8);
  INSERT INTO public."Booking" (
    "MaBooking", "KhachHangID", "HinhThucNhanDo", "DiaChiNhan", "HinhThucTraDo",
    "NgayHen", "GioHen", "GhiChu", "TrangThai", "IdempotencyKey"
  ) VALUES (
    booking_number, customer_id, p_hinhthucnhando,
    nullif(btrim(p_diachinhan), ''), 'Tại cửa hàng', p_ngayhen, p_giohen,
    nullif(btrim(p_ghichu), ''), 'ChoTiepNhan', p_idempotency_key
  ) RETURNING "BookingID" INTO booking_id;
  RETURN jsonb_build_object(
    'bookingid', booking_id,
    'mabooking', booking_number,
    'trangthai', 'ChoTiepNhan',
    'thanhtien', 0,
    'itemcount', 0
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_laundry_order(p_banggiaid bigint, p_measurement numeric, p_hinhthucnhando text, p_diachinhan text, p_ngayhen date, p_giohen time without time zone, p_ghichu text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb; detail_id bigint;
BEGIN
 result:=public.submit_laundry_order_cart(jsonb_build_array(jsonb_build_object('banggiaid',p_banggiaid,'measurement',p_measurement)),p_hinhthucnhando,p_diachinhan,p_ngayhen,p_giohen,p_ghichu,p_idempotency_key);
 SELECT min("ChiTietBookingID") INTO detail_id FROM public."ChiTietBooking" WHERE "BookingID"=(result->>'bookingid')::bigint;
 RETURN result||jsonb_build_object('chitietbookingid',detail_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_laundry_order_cart(p_items jsonb, p_hinhthucnhando text, p_diachinhan text, p_ngayhen date, p_giohen time without time zone, p_ghichu text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 customer_id bigint := private.current_customer_id();
 booking_row public."Booking"%ROWTYPE;
 booking_id bigint;
 detail_count integer := 0;
 total_amount numeric := 0;
 item jsonb;
 price_row record;
 measurement numeric;
 quantity numeric;
 weight_kg numeric;
 line_total numeric;
BEGIN
 IF auth.uid() IS NULL OR customer_id IS NULL THEN RAISE EXCEPTION 'An active customer account is required'; END IF;
 IF p_idempotency_key IS NULL THEN RAISE EXCEPTION 'An idempotency key is required'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_idempotency_key::text,0));
 SELECT * INTO booking_row FROM public."Booking" WHERE "IdempotencyKey"=p_idempotency_key;
 IF FOUND THEN
  IF booking_row."KhachHangID"<>customer_id THEN RAISE EXCEPTION 'Idempotency key is already in use'; END IF;
  SELECT count(*),coalesce(sum("ThanhTien"),0) INTO detail_count,total_amount FROM public."ChiTietBooking" WHERE "BookingID"=booking_row."BookingID";
  RETURN jsonb_build_object('bookingid',booking_row."BookingID",'mabooking',booking_row."MaBooking",'trangthai',booking_row."TrangThai",'thanhtien',total_amount,'itemcount',detail_count);
 END IF;
 IF p_items IS NULL OR jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'Cart must contain at least one item'; END IF;
 IF p_hinhthucnhando IS NULL OR p_hinhthucnhando NOT IN ('Tại cửa hàng','Tại nhà') THEN RAISE EXCEPTION 'Unsupported pickup method'; END IF;
 IF p_hinhthucnhando='Tại nhà' AND nullif(btrim(p_diachinhan),'') IS NULL THEN RAISE EXCEPTION 'A pickup address is required'; END IF;
 IF p_ngayhen IS NULL OR p_ngayhen<current_date OR p_giohen IS NULL THEN RAISE EXCEPTION 'A current pickup appointment is required'; END IF;
 INSERT INTO public."Booking"("MaBooking","KhachHangID","HinhThucNhanDo","DiaChiNhan","HinhThucTraDo","NgayHen","GioHen","GhiChu","TrangThai","IdempotencyKey")
 VALUES('BK-'||substr(replace(gen_random_uuid()::text,'-',''),1,24),customer_id,p_hinhthucnhando,CASE WHEN p_hinhthucnhando='Tại nhà' THEN nullif(btrim(p_diachinhan),'') END,'Tại cửa hàng',p_ngayhen,p_giohen,nullif(btrim(p_ghichu),''),'ChoTiepNhan',p_idempotency_key)
 RETURNING "BookingID" INTO booking_id;
 UPDATE public."Booking" SET "MaBooking"='BK'||lpad(booking_id::text,greatest(4,length(booking_id::text)),'0') WHERE "BookingID"=booking_id;
 FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
  -- A client price ID identifies the tuple, never fixes a stale/future price.
  SELECT bg.*,lower(btrim(coalesce(u."KyHieu",u."TenDonViTinh"))) AS unit_symbol INTO price_row
  FROM public."BangGia" chosen JOIN public."BangGia" bg ON bg."DichVuID"=chosen."DichVuID" AND bg."LoaiDoGiatID"=chosen."LoaiDoGiatID" AND bg."DonViTinhID"=chosen."DonViTinhID"
  JOIN public."DonViTinh" u ON u."DonViTinhID"=bg."DonViTinhID"
  WHERE chosen."BangGiaID"=(item->>'banggiaid')::bigint AND bg."TrangThai"='Hoạt động'
   AND (bg."NgayApDung" IS NULL OR bg."NgayApDung"<=current_date) AND (bg."NgayKetThuc" IS NULL OR bg."NgayKetThuc">=current_date)
  ORDER BY bg."NgayApDung" DESC NULLS LAST,bg."BangGiaID" DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'No effective price is available for the selected tuple'; END IF;
  measurement := (item->>'measurement')::numeric;
  IF measurement IS NULL OR measurement<=0 OR measurement>99999999.99 THEN RAISE EXCEPTION 'Invalid measurement'; END IF;
  IF price_row.unit_symbol IN ('kg','kgs','kilogram') THEN
   measurement:=round(measurement,2);
   IF measurement<=0 THEN RAISE EXCEPTION 'Invalid measurement'; END IF;
   weight_kg := measurement; quantity := NULL;
   line_total := round(price_row."DonGia"*greatest(measurement,3),0);
  ELSE
   IF measurement<>trunc(measurement) THEN RAISE EXCEPTION 'Piece quantity must be an integer'; END IF;
   quantity := measurement; weight_kg := NULL;
   line_total := round(price_row."DonGia"*measurement,0);
  END IF;
  INSERT INTO public."ChiTietBooking"("BookingID","DichVuID","LoaiDoGiatID","DonViTinhID","SoLuong","KhoiLuong","DonGia","ThanhTien","GhiChu")
  VALUES(booking_id,price_row."DichVuID",price_row."LoaiDoGiatID",price_row."DonViTinhID",quantity,weight_kg,price_row."DonGia",line_total,nullif(btrim(p_ghichu),''));
  detail_count:=detail_count+1;total_amount:=total_amount+line_total;
 END LOOP;
 SELECT * INTO booking_row FROM public."Booking" WHERE "BookingID"=booking_id;
 RETURN jsonb_build_object('bookingid',booking_id,'mabooking',booking_row."MaBooking",'trangthai','ChoTiepNhan','thanhtien',total_amount,'itemcount',detail_count);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_laundry_order_cart_with_points(p_items jsonb, p_hinhthucnhando text, p_diachinhan text, p_ngayhen date, p_giohen time without time zone, p_ghichu text, p_idempotency_key uuid, p_use_points boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 result jsonb; booking_row public."Booking"%ROWTYPE;
 customer_id bigint:=private.current_customer_id(); available_points integer; requested_points integer; total_amount numeric;
BEGIN
 result:=public.submit_laundry_order_cart(p_items,p_hinhthucnhando,p_diachinhan,p_ngayhen,p_giohen,p_ghichu,p_idempotency_key);
 SELECT * INTO booking_row FROM public."Booking" WHERE "BookingID"=(result->>'bookingid')::bigint AND "KhachHangID"=customer_id FOR UPDATE;
 SELECT coalesce("DiemHienTai",0) INTO available_points FROM public."DiemTichLuy" WHERE "KhachHangID"=customer_id;
 available_points:=coalesce(available_points,0);total_amount:=(result->>'thanhtien')::numeric;
 -- Preserve an old reservation on replay. New bookings store intent only.
 IF booking_row."TrangThai"='ChoTiepNhan' AND NOT booking_row."DiemDaTru" THEN
  requested_points:=CASE WHEN coalesce(p_use_points,false) THEN least(available_points::numeric,floor(total_amount))::integer ELSE 0 END;
  UPDATE public."Booking" SET "DiemSuDung"=requested_points,"TienGiamDoDiem"=requested_points,"DiemDaTru"=false WHERE "BookingID"=booking_row."BookingID" RETURNING * INTO booking_row;
 END IF;
 RETURN result||jsonb_build_object('diemsudung',booking_row."DiemSuDung",'tiengiamdodiem',booking_row."TienGiamDoDiem",'thanhtoan',greatest(total_amount-booking_row."TienGiamDoDiem",0),'diemconlai',available_points,'diemdadatru',booking_row."DiemDaTru");
END;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_order_review(p_donhangid bigint, p_sosao integer, p_binhluan text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_id bigint := (SELECT private.current_customer_id());
  review_id bigint;
BEGIN
  IF customer_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_sosao < 1 OR p_sosao > 5 THEN
    RAISE EXCEPTION 'Rating must be between 1 and 5';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public."DonHang" AS order_record
    WHERE order_record."DonHangID" = p_donhangid
      AND order_record."KhachHangID" = customer_id
      AND order_record."TrangThai" IN ('Đã giao', 'Đã thanh toán')
  ) THEN
    RAISE EXCEPTION 'Only completed customer orders can be reviewed';
  END IF;

  INSERT INTO public."DanhGia" (
    "DonHangID", "KhachHangID", "SoSao", "BinhLuan", "NgayDanhGia", "TrangThai"
  ) VALUES (
    p_donhangid::integer,
    customer_id::integer,
    p_sosao,
    nullif(left(btrim(p_binhluan), 1000), ''),
    now(),
    'Hiển thị'
  )
  ON CONFLICT ("DonHangID") DO UPDATE
  SET "SoSao" = EXCLUDED."SoSao",
      "BinhLuan" = EXCLUDED."BinhLuan",
      "NgayDanhGia" = now(),
      "TrangThai" = 'Hiển thị'
  RETURNING "DanhGiaID" INTO review_id;

  RETURN jsonb_build_object('danhgiaid', review_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.transition_laundry_order(p_donhangid bigint, p_trangthaimoi text, p_lydo text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  order_record public."DonHang"%ROWTYPE;
  valid_transition boolean := false;
  current_employee bigint := (SELECT private.current_employee_id());
  current_account bigint := (
    SELECT "TaiKhoanID"
    FROM public."TaiKhoan"
    WHERE "UserAuthId" = (SELECT auth.uid())
    LIMIT 1
  );
  customer_account_id bigint;
BEGIN
  IF (SELECT auth.uid()) IS NULL
     OR NOT (SELECT private.is_staff())
     OR (
       current_employee IS NULL
       AND NOT (SELECT private.has_role('Quản lý'))
       AND NOT (SELECT private.has_role('Chủ cửa hàng'))
     ) THEN
    RAISE EXCEPTION 'An active staff account is required';
  END IF;
  SELECT *
  INTO order_record
  FROM public."DonHang"
  WHERE "DonHangID" = p_donhangid
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;
  IF p_trangthaimoi=order_record."TrangThai" THEN RETURN; END IF;
  valid_transition := CASE order_record."TrangThai"
    WHEN 'Chờ tiếp nhận' THEN p_trangthaimoi = 'Đã hủy'
    WHEN 'Đã tiếp nhận' THEN p_trangthaimoi IN ('Đang giặt', 'Đã hủy')
    WHEN 'Đang giặt' THEN p_trangthaimoi = 'Hoàn thành giặt'
    WHEN 'Hoàn thành giặt' THEN p_trangthaimoi IN ('Đang giao', 'Đã giao')
    WHEN 'Đang giao' THEN p_trangthaimoi = 'Đã giao'
    ELSE false
  END;
  IF NOT valid_transition THEN
    RAISE EXCEPTION 'Invalid order status transition: % -> %',
      order_record."TrangThai", p_trangthaimoi;
  END IF;
  IF p_trangthaimoi = 'Đã hủy' AND nullif(btrim(p_lydo), '') IS NULL THEN
    RAISE EXCEPTION 'A cancellation reason is required';
  END IF;
  IF p_trangthaimoi='Đã hủy' AND EXISTS (SELECT 1 FROM public."ThanhToan" WHERE "DonHangID"=p_donhangid AND "TrangThai"='Thành công') THEN RAISE EXCEPTION 'Collected payments must be refunded before cancellation'; END IF;
  UPDATE public."DonHang"
  SET "TrangThai" = p_trangthaimoi,
      "NgayCapNhat" = now()
  WHERE "DonHangID" = p_donhangid;
  INSERT INTO public."NhatKyHeThong" (
    "TaiKhoanID", "HanhDong", "BangDuLieu", "BanGhiID",
    "DuLieuCu", "DuLieuMoi", "LyDo", "ThoiGian"
  ) VALUES (
    current_account,
    'Thay đổi trạng thái đơn hàng',
    'DonHang',
    p_donhangid,
    jsonb_build_object('TrangThai', order_record."TrangThai"),
    jsonb_build_object('TrangThai', p_trangthaimoi),
    nullif(left(btrim(p_lydo), 500), ''),
    now()
  );
  customer_account_id := private.account_id_for_customer(order_record."KhachHangID");
  IF customer_account_id IS NOT NULL THEN
    INSERT INTO public."ThongBao" (
      "TaiKhoanID", "TieuDe", "NoiDung", "ThoiGianGui", "DaDoc", "DonHangID", "LoaiThongBao"
    ) VALUES (
      customer_account_id,
      CASE WHEN p_trangthaimoi = 'Đã hủy'
        THEN 'Đơn hàng đã bị hủy'
        ELSE 'Cập nhật trạng thái đơn hàng'
      END,
      'Đơn hàng ' || order_record."MaDonHang" || ' đã chuyển sang trạng thái: ' || p_trangthaimoi || '.',
      now(),
      false,
      p_donhangid,
      CASE WHEN p_trangthaimoi = 'Đã hủy' THEN 'order_cancelled' ELSE 'status_update' END
    );
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_customer_profile(p_full_name text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_address text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_id bigint := (SELECT private.current_customer_id());
  account_id bigint;
BEGIN
  IF customer_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF nullif(btrim(p_full_name), '') IS NULL THEN
    RAISE EXCEPTION 'Full name is required';
  END IF;

  SELECT "TaiKhoanID"
  INTO account_id
  FROM public."TaiKhoan"
  WHERE "KhachHangID" = customer_id
    AND "UserAuthId" = (SELECT auth.uid())
  LIMIT 1;

  UPDATE public."KhachHang"
  SET "HoTen" = left(btrim(p_full_name), 150),
      "Email" = nullif(left(btrim(p_email), 255), ''),
      "SoDienThoai" = nullif(left(btrim(p_phone), 20), ''),
      "DiaChi" = nullif(left(btrim(p_address), 255), '')
  WHERE "KhachHangID" = customer_id;

  UPDATE public."TaiKhoan"
  SET "Email" = nullif(left(btrim(p_email), 255), ''),
      "SoDienThoai" = nullif(left(btrim(p_phone), 20), '')
  WHERE "TaiKhoanID" = account_id;

  RETURN jsonb_build_object('khachhangid', customer_id, 'taikhoanid', account_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_customer_profile_with_avatar(p_full_name text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  customer_id bigint := (SELECT private.current_customer_id());
  account_id bigint;
BEGIN
  IF customer_id IS NULL OR nullif(btrim(p_full_name), '') IS NULL THEN
    RAISE EXCEPTION 'Invalid customer profile';
  END IF;

  SELECT "TaiKhoanID"
  INTO account_id
  FROM public."TaiKhoan"
  WHERE "KhachHangID" = customer_id
    AND "UserAuthId" = (SELECT auth.uid());

  UPDATE public."KhachHang"
  SET "HoTen" = left(btrim(p_full_name), 150),
      "Email" = nullif(left(btrim(p_email), 255), ''),
      "SoDienThoai" = nullif(left(btrim(p_phone), 20), ''),
      "DiaChi" = nullif(left(btrim(p_address), 255), ''),
      "AvatarUrl" = coalesce(nullif(btrim(p_avatar_url), ''), "AvatarUrl")
  WHERE "KhachHangID" = customer_id;

  UPDATE public."TaiKhoan"
  SET "Email" = nullif(left(btrim(p_email), 255), ''),
      "SoDienThoai" = nullif(left(btrim(p_phone), 20), '')
  WHERE "TaiKhoanID" = account_id;

  RETURN jsonb_build_object('khachhangid', customer_id);
END;
$function$
;

CREATE TRIGGER notify_booking_created AFTER INSERT ON "Booking" FOR EACH ROW EXECUTE FUNCTION private.notify_booking_created();

CREATE TRIGGER notify_customer_booking_changed AFTER UPDATE ON "Booking" FOR EACH ROW WHEN (old.* IS DISTINCT FROM new.*) EXECUTE FUNCTION private.notify_customer_booking_changed();

CREATE TRIGGER notify_customer_booking_deleted AFTER DELETE ON "Booking" FOR EACH ROW EXECUTE FUNCTION private.notify_customer_booking_deleted();

CREATE TRIGGER apply_booking_promotion_to_order BEFORE INSERT OR UPDATE ON "DonHang" FOR EACH ROW EXECUTE FUNCTION private.apply_booking_promotion_to_order();

CREATE TRIGGER laundry_compat_create_order_invoice AFTER INSERT ON "DonHang" FOR EACH ROW EXECUTE FUNCTION private.create_legacy_order_invoice();

CREATE TRIGGER laundry_compat_record_order_insert AFTER INSERT ON "DonHang" FOR EACH ROW EXECUTE FUNCTION private.record_legacy_order_status_change();

CREATE TRIGGER laundry_compat_record_order_status AFTER UPDATE OF "TrangThai" ON "DonHang" FOR EACH ROW EXECUTE FUNCTION private.record_legacy_order_status_change();

CREATE TRIGGER notify_customer_order_changed AFTER INSERT OR UPDATE ON "DonHang" FOR EACH ROW EXECUTE FUNCTION private.notify_customer_order_changed();

CREATE TRIGGER set_booking_delivery_fee_on_order BEFORE INSERT ON "DonHang" FOR EACH ROW EXECUTE FUNCTION private.copy_booking_delivery_fee_to_order();

CREATE TRIGGER notify_customers_new_promotion AFTER INSERT ON "KhuyenMai" FOR EACH ROW EXECUTE FUNCTION private.notify_customers_new_promotion();

CREATE TRIGGER notify_customer_of_store_message AFTER INSERT ON "TinNhan" FOR EACH ROW EXECUTE FUNCTION notify_customer_of_store_message();

CREATE TRIGGER web_message_changed AFTER INSERT OR DELETE OR UPDATE ON "TinNhan" FOR EACH ROW EXECUTE FUNCTION private.broadcast_web_message_change();

ALTER TABLE "private"."web_message_channels" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."BangGia" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."Booking" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."ChiTietBooking" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."ChiTietDonHang" ENABLE ROW LEVEL SECURITY;

