CREATE POLICY "avatar owners read" ON "storage"."objects" AS PERMISSIVE FOR SELECT TO "authenticated" USING (((bucket_id = 'avatars'::text) AND (owner_id = ( SELECT (auth.uid())::text AS uid))));

CREATE POLICY "avatar owners update" ON "storage"."objects" AS PERMISSIVE FOR UPDATE TO "authenticated" USING (((bucket_id = 'avatars'::text) AND (owner_id = ( SELECT (auth.uid())::text AS uid)))) WITH CHECK (((bucket_id = 'avatars'::text) AND (owner_id = ( SELECT (auth.uid())::text AS uid))));

CREATE POLICY "avatar owners upload" ON "storage"."objects" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK (((bucket_id = 'avatars'::text) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid))));

